const transactionsForSharing = `-- name: TransactionsForSharing :many
SELECT t.id, t.account_id, t.fingerprint, t.occurrence, t.split_scope, t.booked_on, t.amount_minor, t.currency,
       t.payee, t.note, coalesce(c.name, '')::text AS category_name,
       g.shared_group_id, l.expense_id AS linked_expense, e.group_id AS linked_group
FROM transactions t
LEFT JOIN categories c ON c.id = t.category_id
LEFT JOIN groups g ON g.id = t.group_id
LEFT JOIN shared_expense_links l ON l.user_id = t.user_id AND (l.account_id, l.fingerprint, l.occurrence, l.split_scope) = (t.account_id, t.fingerprint, t.occurrence, t.split_scope)
LEFT JOIN shared_expenses e ON e.id = l.expense_id
WHERE t.user_id = $1 AND t.id = ANY($2::uuid[])
  AND (g.shared_group_id IS NOT NULL OR l.expense_id IS NOT NULL)
ORDER BY t.seq
`

type TransactionsForSharingParams struct {
	UserID uuid.UUID
	Ids    []uuid.UUID
}

type TransactionsForSharingRow struct {
	ID            uuid.UUID
	AccountID     uuid.UUID
	Fingerprint   []byte
	Occurrence    int32
	SplitScope    uuid.UUID
	BookedOn      platform.Date
	AmountMinor   int64
	Currency      string
	Payee         string
	Note          string
	CategoryName  string
	SharedGroupID *uuid.UUID
	LinkedExpense *uuid.UUID
	LinkedGroup   *uuid.UUID
}

// The given transactions with what a shared copy needs, the shared group their personal group is
// linked to, and their current copy (through the user's private link). Only rows that are linked or
// already shared come back, so a bulk edit without sharing costs one cheap query.
func (q *Queries) TransactionsForSharing(ctx context.Context, arg TransactionsForSharingParams) ([]TransactionsForSharingRow, error) {
	rows, err := q.db.Query(ctx, transactionsForSharing, arg.UserID, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TransactionsForSharingRow
	for rows.Next() {
		var i TransactionsForSharingRow
		if err := rows.Scan(
			&i.ID,
			&i.AccountID,
			&i.Fingerprint,
			&i.Occurrence,
			&i.SplitScope,
			&i.BookedOn,
			&i.AmountMinor,
			&i.Currency,
			&i.Payee,
			&i.Note,
			&i.CategoryName,
			&i.SharedGroupID,
			&i.LinkedExpense,
			&i.LinkedGroup,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

