const updateSharedGroup = `-- name: UpdateSharedGroup :one
UPDATE shared_groups
SET name = $1, color = $2, kind = $3, starts_on = $4, ends_on = $5,
    budget_minor = $6, archived_at = $7
WHERE id = $8
RETURNING id, owner_id, name, color, currency, kind, starts_on, ends_on, budget_minor, archived_at, created_at
`

type UpdateSharedGroupParams struct {
	Name        string
	Color       int16
	Kind        string
	StartsOn    *platform.Date
	EndsOn      *platform.Date
	BudgetMinor *int64
	ArchivedAt  *time.Time
	ID          uuid.UUID
}

func (q *Queries) UpdateSharedGroup(ctx context.Context, arg UpdateSharedGroupParams) (SharedGroup, error) {
	row := q.db.QueryRow(ctx, updateSharedGroup,
		arg.Name,
		arg.Color,
		arg.Kind,
		arg.StartsOn,
		arg.EndsOn,
		arg.BudgetMinor,
		arg.ArchivedAt,
		arg.ID,
	)
	var i SharedGroup
	err := row.Scan(
		&i.ID,
		&i.OwnerID,
		&i.Name,
		&i.Color,
		&i.Currency,
		&i.Kind,
		&i.StartsOn,
		&i.EndsOn,
		&i.BudgetMinor,
		&i.ArchivedAt,
		&i.CreatedAt,
	)
	return i, err
}

const upsertSharedLink = `-- name: UpsertSharedLink :exec
INSERT INTO shared_expense_links (user_id, account_id, fingerprint, occurrence, split_scope, expense_id)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (account_id, fingerprint, occurrence, split_scope) DO UPDATE SET expense_id = excluded.expense_id
`

type UpsertSharedLinkParams struct {
	UserID      uuid.UUID
	AccountID   uuid.UUID
	Fingerprint []byte
	Occurrence  int32
	SplitScope  uuid.UUID
	ExpenseID   uuid.UUID
}

func (q *Queries) UpsertSharedLink(ctx context.Context, arg UpsertSharedLinkParams) error {
	_, err := q.db.Exec(ctx, upsertSharedLink,
		arg.UserID,
		arg.AccountID,
		arg.Fingerprint,
		arg.Occurrence,
		arg.SplitScope,
		arg.ExpenseID,
	)
	return err
}
